import{_ as a,C as r,o as i,c as o,ag as s,E as n}from"./chunks/framework.cyF4XceO.js";const g=JSON.parse('{"title":"Versions and compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"docs/versions.md","filePath":"docs/versions.md"}'),d={name:"docs/versions.md"};function c(l,e,h,p,m,u){const t=r("StatusNote");return i(),o("div",null,[e[0]||(e[0]=s(`<h1 id="versions-and-compatibility" tabindex="-1">Versions and compatibility <a class="header-anchor" href="#versions-and-compatibility" aria-label="Permalink to &quot;Versions and compatibility&quot;">​</a></h1><p>Takoform has exactly two domain version axes: the public API/Core release SemVer and each Form&#39;s own <code>definitionVersion</code>. API/Core releases are human-readable compatibility checkpoints; they do not rename the wire or discovery lane. Provider SemVer, package and schema IDs or digests, Interface/Binding references, Specification releases, and retained lanes are artifact/history identities rather than additional domain axes.</p><p>The frozen predecessor source remains at <a href="https://github.com/tako0614/terraform-provider-takoform/blob/896fb0e6c94557d97ba7445924fda18a8430ba8f/spec/versioning.md" target="_blank" rel="noreferrer"><code>spec/versioning.md</code></a>. These current Provider pages are maintained separately from that historical file.</p><h2 id="current-design-target" tabindex="-1">Current design target <a class="header-anchor" href="#current-design-target" aria-label="Permalink to &quot;Current design target&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Domain axis</th><th>Current identity</th><th>Meaning and availability</th></tr></thead><tbody><tr><td>API/Core release SemVer</td><td><strong><code>1.0.1</code></strong> (<a href="https://github.com/tako0614/takoform/releases/tag/v1.0.1" target="_blank" rel="noreferrer">public Core release</a>)</td><td>Public compatibility checkpoint on the <code>forms.takoform.com/v1</code> wire/discovery lane. Every compatible <code>1.y.0</code> checkpoint remains on <code>/v1</code>; Host implementation/support/deployment remains separate.</td></tr><tr><td>Form <code>definitionVersion</code> (active publisher)</td><td><strong>1 family / 16 candidate Forms</strong></td><td>The standalone <a href="https://github.com/tako0614/takoform-forms" target="_blank" rel="noreferrer"><code>takoform-forms</code></a> source currently carries <code>edge.forms.takoform.com</code>; package artifacts are unpublished and each Form advances independently.</td></tr></tbody></table><h2 id="api-core-release-checkpoints" tabindex="-1">API/Core release checkpoints <a class="header-anchor" href="#api-core-release-checkpoints" aria-label="Permalink to &quot;API/Core release checkpoints&quot;">​</a></h2><p>The current public API/Core checkpoint is <strong><code>v1.0.1</code></strong>, recorded by the <a href="https://github.com/tako0614/takoform/releases/tag/v1.0.1" target="_blank" rel="noreferrer">Takoform Core release</a> at commit <code>8da857ca21e90d4e46edb2e3f53197dbd1df0f3b</code>. It uses the existing <code>forms.takoform.com/v1</code> wire and discovery lane. The release number is a human-readable compatibility checkpoint, not a URL path. Compatible <code>1.x</code> checkpoints remain on <code>/v1</code>; Host implementation, deployment, support, and adoption remain host-owned facts. A protocol-breaking major gets a new lane only through an explicit Core decision.</p><p>The historical <strong>Specification 1.1</strong> is a sealed exact source receipt in the predecessor release ledger. It is not API release <code>1.1</code> or <code>1.1.0</code>, does not create <code>/v1.1</code>, and is not an ongoing Specification version stream. Future checkpoints are API/Core releases, not new Specification numbers.</p><h2 id="artifact-and-history-identities" tabindex="-1">Artifact and history identities <a class="header-anchor" href="#artifact-and-history-identities" aria-label="Permalink to &quot;Artifact and history identities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Identity</th><th>Current or retained meaning</th></tr></thead><tbody><tr><td>Specification <strong>1.1</strong></td><td>Sealed historical identity of one exact normative source snapshot. It is not API release 1.1, does not publish or promote the <code>/v1</code> wire lane, a Form, a package, or Provider 3, and is not an ongoing version stream. Identity 1.0 was withdrawn before publication and may not be reused.</td></tr><tr><td>Host API wire/discovery lane <strong><code>forms.takoform.com/v1</code></strong></td><td>The protocol path used by the API/Core <code>1.x</code> compatibility checkpoints; the path is not a third domain version axis.</td></tr><tr><td>Form Family group</td><td>Versionless namespace in each exact FormRef; older versioned groups remain retained or withdrawn history.</td></tr><tr><td>Form Package envelope <strong><code>packages.forms.takoform.com/v1alpha5</code></strong></td><td>Manifest-format identifier. Package IDs and content digests identify artifact bytes, and package publication remains independent of Provider publication.</td></tr><tr><td>Schema IDs and digests</td><td>Exact Definition or wire-schema bytes, not a second Form version.</td></tr><tr><td>Interface/Binding refs and digests</td><td>Exact operation-surface and typed-capability contracts referenced by Forms.</td></tr><tr><td>Provider <strong>3.0.0</strong>, Registry-published</td><td>Non-normative Terraform/OpenTofu client distribution retaining the Provider 3 typed mapping.</td></tr><tr><td>Provider <strong>2.1.1</strong>, Registry-published</td><td>Retained Beta <code>v1beta1</code> client for the 15 immutable <code>edge.forms.takoform.com/v1beta1</code> FormRefs; its identity is recorded in the <a href="/release/provider-form-identities.json">provider Form identity ledger</a>.</td></tr><tr><td>Providers <strong>2.0.0</strong> and <strong>1.0.3</strong></td><td>Withdrawn pre-Beta client identities; immutable Registry history for exact-pin recovery and migration only.</td></tr></tbody></table><p>Provider distribution is an artifact identity, not a domain axis. <strong>Provider 3.0.0</strong> is the current Registry-published implementation. <strong>Provider 2.1.1</strong> is retained Beta <code>v1beta1</code> history: it targets Host API <code>forms.takoform.com/v1beta1</code> and the <code>edge.forms.takoform.com/v1beta1</code> family, and remains installable for the exact FormRefs recorded in the <a href="/release/provider-form-identities.json">provider Form identity ledger</a>. By contrast, <strong>Provider 2.0.0</strong> and <strong>Provider 1.0.3</strong> are the withdrawn pre-Beta epochs; their Registry identities remain immutable history for exact-pin recovery and migration (<a href="/spec/decisions/0042-the-pre-beta-epochs-are-withdrawn.html">decision 0042</a>). Provider 3 is a client artifact identity: it cannot block or authorize the API/Core <code>1.0.1</code> release or the sealed Specification 1.1 receipt, and publishing a new Form <code>definitionVersion</code> does not wait for a Provider release.</p><h2 id="published-compatibility-mapping" tabindex="-1">Published compatibility mapping <a class="header-anchor" href="#published-compatibility-mapping" aria-label="Permalink to &quot;Published compatibility mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Client or distribution</th><th>Host API</th><th>Forms and definitions</th><th>Status / use</th></tr></thead><tbody><tr><td>Provider 3.0.0 distribution</td><td>API/Core <code>v1.0.1</code> on Host API wire v1</td><td>8-family / 31-Form retained typed compatibility mapping</td><td>Current Registry-published non-normative Provider history; not the active publisher roster.</td></tr><tr><td>Provider 2.1.1 distribution</td><td>Host API v1beta1</td><td>Edge Form Family v1beta1; 15 immutable historical Form identities</td><td>Registry-published retained client; descriptor remains <code>candidate-only</code> metadata by design.</td></tr><tr><td>Provider 2.0.0 distribution</td><td>Host API v1alpha2 (withdrawn epoch)</td><td>The nine withdrawn v1alpha2 Forms</td><td>Immutable Registry history; exact-pin only, no successors.</td></tr><tr><td>Provider 1.0.3 Legacy</td><td>Host API v1alpha1 (withdrawn epoch)</td><td>The withdrawn v1 Form Package identities</td><td>Immutable Registry history; recovery and migration only.</td></tr></tbody></table><p>The API/Core <code>1.0.1</code> checkpoint, its Host API wire/discovery path, and the versionless Form families are not interchangeable labels. A Form&#39;s own <code>definitionVersion</code> is the only per-Form domain version; it does not change the API/Core release or Provider SemVer. The sealed Specification 1.1 receipt does not silently become API release 1.1 or mint stable Form identities, and a new Form publication does not require a Provider release.</p><h2 id="current-edge-reference-family-16-experimental-forms" tabindex="-1">Current Edge reference family (16 Experimental Forms) <a class="header-anchor" href="#current-edge-reference-family-16-experimental-forms" aria-label="Permalink to &quot;Current Edge reference family (16 Experimental Forms)&quot;">​</a></h2><p>The current Edge family is versionless and contains these 16 exact Experimental <code>0.x</code> Forms:</p><ul><li><a href="/docs/resources/module_worker.html"><code>takoform_module_worker</code></a></li><li><a href="/docs/resources/worker_bundle.html"><code>takoform_worker_bundle</code></a></li><li><a href="/docs/resources/static_asset_bundle.html"><code>takoform_static_asset_bundle</code></a></li><li><a href="/docs/resources/worker_version.html"><code>takoform_worker_version</code></a></li><li><a href="/docs/resources/worker_deployment.html"><code>takoform_worker_deployment</code></a></li><li><a href="/docs/resources/worker_custom_domain.html"><code>takoform_worker_custom_domain</code></a></li><li><a href="/docs/resources/worker_endpoint.html"><code>takoform_worker_endpoint</code></a></li><li><a href="/docs/resources/worker_cron_trigger.html"><code>takoform_worker_cron_trigger</code></a></li><li><a href="/docs/resources/edge_kv_namespace.html"><code>takoform_edge_kv_namespace</code></a></li><li><a href="/docs/resources/sqlite_database.html"><code>takoform_sqlite_database</code></a></li><li><a href="/docs/resources/sqlite_migration_set.html"><code>takoform_sqlite_migration_set</code></a></li><li><a href="/docs/resources/sqlite_migration_application.html"><code>takoform_sqlite_migration_application</code></a></li><li><a href="/docs/resources/at_least_once_queue.html"><code>takoform_at_least_once_queue</code></a></li><li><a href="/docs/resources/queue_consumer.html"><code>takoform_queue_consumer</code></a></li><li><a href="/docs/resources/durable_workflow.html"><code>takoform_durable_workflow</code></a></li><li><a href="/docs/resources/actor_namespace.html"><code>takoform_actor_namespace</code></a></li></ul><p>The independent Registry-published Provider 3 uses these resource names without making them normative or changing Form maturity:</p><div class="language-hcl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">hcl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">terraform</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  required_providers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    takoform</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      source  </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;registry.terraform.io/tako0614/takoform&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      version </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&gt;= 3.0.0&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Provider 2.1.1 remains available for the exact retained Beta identities it shipped; Provider 3&#39;s 31 mappings are retained compatibility history and must not be read as the active standalone publisher&#39;s 16-Form candidate set.</p><h2 id="release-cadence-and-gates" tabindex="-1">Release cadence and gates <a class="header-anchor" href="#release-cadence-and-gates" aria-label="Permalink to &quot;Release cadence and gates&quot;">​</a></h2><p>API patch releases are defect-only and may be batched. Minor checkpoints are at most monthly and may be skipped. A major checkpoint is normally at most annual and requires a concrete incompatibility and migration plan. Before publication, the owning source is reviewed and its release gate passes; after publication, the checkpoint is read-only. Form definition and package releases follow the publisher&#39;s independent cadence, while Provider releases occur only when its typed adapter/compatibility surface changes.</p><h2 id="publisher-parity-at-the-form-package-boundary" tabindex="-1">Publisher parity at the Form/Package boundary <a class="header-anchor" href="#publisher-parity-at-the-form-package-boundary" aria-label="Permalink to &quot;Publisher parity at the Form/Package boundary&quot;">​</a></h2><p>Official and external/third-party publishers are equal at the Form and Form Package publication boundary. Only the publisher identity and domain differ; the contract, verification, trust/admission, lifecycle, and authority rules do not. An official namespace confers no stronger semantics. Operators explicitly choose the trusted source, issuer, signature/revocation policy, and Host Support policy; publisher provenance is not part of FormRef equality.</p><h2 id="withdrawn-epochs" tabindex="-1">Withdrawn epochs <a class="header-anchor" href="#withdrawn-epochs" aria-label="Permalink to &quot;Withdrawn epochs&quot;">​</a></h2><p>The pre-Beta epochs and their documentation were withdrawn (<a href="/spec/decisions/0042-the-pre-beta-epochs-are-withdrawn.html">decision 0042</a>). The withdrawn resource pages no longer exist on this site; the identities are recorded as retired in the published ledgers, and the bytes stay in the repository&#39;s git history and release tags. Existing users of the withdrawn resources keep an exact pin (<code>= 2.0.0</code>, <code>= 1.0.3</code> for v1 state) or follow the <a href="/release/migrations/v2-to-v3.html">v2 to v3 migration boundary</a>: stay pinned, remove from state, or destroy while still pinned. Nothing is migrated automatically, and upgrading past the withdrawal with one of the nine still in state fails closed before any lifecycle request.</p>`,26)),n(t)])}const b=a(d,[["render",c]]);export{g as __pageData,b as default};
